#pragma once

#include "p2pdc/attempt_guard.h"
#include "p2pdc/handshake.h"

namespace p2pdc::detail {

enum class SessionError {
    InvalidBinding,
    WrongCapability,
    WrongKind,
    DuplicateDescription,
    MissingDescription,
    SequenceExhausted
};
template <class T>
using SessionResult = std::variant<T, SessionError, AttemptDecision, SignalingError, CryptoError>;

// Internal per-attempt verifier. The caller must authorize the expected remote
// signing key, supply a fresh unpredictable attempt ID, and use the exact local
// SDP generated by the transport and the returned remote SDP when configuring it.
// The recipient box key must come from the matching verified advertisement.
// Each encoded record must be retained for retransmission: a second call uses a
// new sequence. Candidate ordering, timeouts and storage delivery are external.
// Capability bytes are not retained. Methods run on one serialized context.
class SignalingSession {
  public:
    SignalingSession(SignalingRecipient local, SignalingRecipient remote,
                     RecipientBoxPublicKey local_box, RecipientBoxPublicKey remote_box,
                     AttemptId attempt, HandshakeRole role, ByteView capability,
                     std::uint8_t max_forward_jump);
    SignalingSession(const SignalingSession &) = delete;
    SignalingSession &operator=(const SignalingSession &) = delete;
    [[nodiscard]] SessionResult<Bytes> encode(const Identity &identity,
                                              const RecipientBoxPublicKey &remote_box,
                                              ByteView capability, SignalingKind kind,
                                              ByteView payload, std::uint64_t issued,
                                              std::uint64_t expiry, SignalingPolicy policy);
    [[nodiscard]] SessionResult<SignalingEnvelope> verify(ByteView wire,
                                                          const RecipientKeyPair &local_box,
                                                          ByteView capability,
                                                          SignalingPolicy policy);
    [[nodiscard]] SessionResult<HandshakeContext> handshake_context() const;

  private:
    [[nodiscard]] bool capability_matches(ByteView capability) const;
    [[nodiscard]] SessionResult<Bytes> encode_checked(const Identity &identity,
                                                      const RecipientBoxPublicKey &remote_box,
                                                      ByteView capability, SignalingKind kind,
                                                      ByteView payload, std::uint64_t issued,
                                                      std::uint64_t expiry, SignalingPolicy policy);
    [[nodiscard]] SessionResult<SignalingEnvelope> accept_verified(SignalingEnvelope envelope,
                                                                   SignalingPolicy policy);
    SignalingRecipient local_;
    SignalingRecipient remote_;
    RecipientBoxPublicKey local_box_;
    RecipientBoxPublicKey remote_box_;
    AttemptId attempt_;
    HandshakeRole role_;
    HandshakeHash group_;
    AttemptGuard guard_;
    std::optional<HandshakeHash> local_sdp_;
    std::optional<HandshakeHash> remote_sdp_;
    std::uint64_t next_sequence_ = 0;
    bool sequence_exhausted_ = false;
};

} // namespace p2pdc::detail
